[CmdletBinding(SupportsShouldProcess=$true,ConfirmImpact='High')]
param([string]$InstallRoot=(Join-Path $HOME '.agent-engineering'))
$ErrorActionPreference='Stop'
function Remove-Block([string]$Path){if(-not(Test-Path $Path)){return};$t=Get-Content $Path -Raw -Encoding UTF8;$p='(?s)\s*<!-- AGENT-ENGINEERING-TOOLKIT:BEGIN -->.*?<!-- AGENT-ENGINEERING-TOOLKIT:END -->\s*';$n=[regex]::Replace($t,$p,"`r`n").Trim();if($PSCmdlet.ShouldProcess($Path,'Remove Toolkit marker block')){Set-Content $Path $n -Encoding UTF8}}
$codex=if($env:CODEX_HOME){$env:CODEX_HOME}else{Join-Path $HOME '.codex'};$claude=if($env:CLAUDE_CONFIG_DIR){$env:CLAUDE_CONFIG_DIR}else{Join-Path $HOME '.claude'};$gemini=Join-Path $HOME '.gemini'
Remove-Block (Join-Path $codex 'AGENTS.md');Remove-Block (Join-Path $codex 'AGENTS.override.md');Remove-Block (Join-Path $claude 'CLAUDE.md');Remove-Block (Join-Path $gemini 'GEMINI.md')
$skills=@('contract-impact-check','stage-execution','independent-review');foreach($s in $skills){foreach($p in @((Join-Path $HOME ".agents\skills\$s"),(Join-Path $claude "skills\$s"),(Join-Path $gemini "config\skills\$s"))){if(Test-Path(Join-Path $p '.agent-engineering-managed')){if($PSCmdlet.ShouldProcess($p,'Remove Toolkit-managed skill')){Remove-Item $p -Recurse -Force}}};$flat=Join-Path $gemini "antigravity-cli\skills\$s.md";$side=Join-Path $gemini "antigravity-cli\skills\$s.agent-engineering-managed";if(Test-Path $side){if($PSCmdlet.ShouldProcess($flat,'Remove Toolkit-managed CLI skill')){Remove-Item $flat,$side -Force -ErrorAction SilentlyContinue}}}
if(Test-Path $InstallRoot){if($PSCmdlet.ShouldProcess($InstallRoot,'Remove installed Toolkit canonical root')){Remove-Item $InstallRoot -Recurse -Force}}
